package cspbuilder

import (
	"errors"
	"fmt"
	"sort"
	"strings"
	"unicode"
)

// Nonce is a special source expression that reserves a slot for the per-request
// nonce generated by the secure middleware. When the built policy is passed to
// secure.Options.ContentSecurityPolicy or secure.Options.ContentSecurityPolicyReportOnly,
// the slot is expanded to 'nonce-<value>' using the nonce of the current request.
// The nonce only appears in the slots where Nonce was explicitly added;
// it is meaningful for the script-src and style-src directive families.
const Nonce = "$NONCE"

// policyEntry is a single directive declaration with its source expressions.
type policyEntry struct {
	directive string
	sources   []string
}

// PolicyBuilder builds a Content Security Policy by appending source
// expressions per directive. All validation happens at Build time:
// duplicate directives, illegal separator characters, and mutually
// exclusive values are reported as errors. The output order is stable:
// directives are sorted by name, source expressions keep their insertion order.
//
// The zero value is ready to use.
type PolicyBuilder struct {
	entries []policyEntry
}

// Add appends source expressions for the given directive. A directive must
// only be added once; adding the same directive twice is reported as an
// error at Build time. Directives that take no values (e.g.
// upgrade-insecure-requests) can be added without source expressions.
func (builder *PolicyBuilder) Add(directive string, sources ...string) *PolicyBuilder {
	builder.entries = append(builder.entries, policyEntry{directive: directive, sources: sources})

	return builder
}

// MustBuild is like Build but panics if an error occurs.
func (builder *PolicyBuilder) MustBuild() string {
	policy, err := builder.Build()
	if err != nil {
		panic(err)
	}

	return policy
}

// Build creates a content security policy string from the added directives.
func (builder *PolicyBuilder) Build() (string, error) {
	entries := make([]policyEntry, len(builder.entries))
	copy(entries, builder.entries)

	sort.SliceStable(entries, func(i, j int) bool {
		return entries[i].directive < entries[j].directive
	})

	var sb strings.Builder

	seen := make(map[string]struct{}, len(entries))

	for _, entry := range entries {
		if err := validateToken(entry.directive); err != nil {
			return "", fmt.Errorf("invalid directive name %q: %w", entry.directive, err)
		}

		if _, ok := seen[entry.directive]; ok {
			return "", fmt.Errorf("duplicate directive %s", entry.directive)
		}

		seen[entry.directive] = struct{}{}

		sources, err := dedupSources(entry.directive, entry.sources)
		if err != nil {
			return "", err
		}

		if sb.Len() > 0 {
			sb.WriteString("; ")
		}

		sb.WriteString(entry.directive)

		for _, source := range sources {
			sb.WriteString(" ")
			sb.WriteString(source)
		}
	}

	return sb.String(), nil
}

// dedupSources validates the source expressions of a directive, removes
// duplicates while preserving the insertion order, and rejects mutually
// exclusive values.
func dedupSources(directive string, sources []string) ([]string, error) {
	deduped := make([]string, 0, len(sources))
	seen := make(map[string]struct{}, len(sources))

	for _, source := range sources {
		if err := validateToken(source); err != nil {
			return nil, fmt.Errorf("invalid source expression %q for directive %s: %w", source, directive, err)
		}

		if _, ok := seen[source]; ok {
			continue
		}

		seen[source] = struct{}{}

		deduped = append(deduped, source)
	}

	if len(deduped) > 1 {
		if _, ok := seen["'none'"]; ok {
			return nil, fmt.Errorf("'none' must be the only source expression for directive %s", directive)
		}
	}

	return deduped, nil
}

// validateToken ensures a directive name or source expression does not
// contain characters that would break the policy syntax.
func validateToken(token string) error {
	if token == "" {
		return errors.New("value must not be empty")
	}

	if strings.IndexFunc(token, isSeparatorRune) >= 0 {
		return errors.New("value must not contain separators, whitespace, or control characters")
	}

	return nil
}

func isSeparatorRune(r rune) bool {
	return r == ';' || r == ',' || unicode.IsSpace(r) || unicode.IsControl(r)
}
